/**
 * Cloudflare Turnstile server-side verification middleware
 */

// Bypass tokens — generated by frontend when Turnstile script fails to load
const BYPASS_TOKENS = new Set([
  'dev-bypass',
  'bypass-error', 
  'script-load-failed',
  'timeout-bypass',
]);

const verifyTurnstile = async (req, res, next) => {
  const secretKey = process.env.TURNSTILE_SECRET_KEY;

  // Skip in test or if no key configured
  if (!secretKey || process.env.NODE_ENV === 'test') return next();

  const token = req.body['cf-turnstile-response'] || req.body.captchaToken;
  if (!token) {
    return res.status(400).json({ message: 'Captcha verification required.' });
  }

  // ✅ Allow bypass tokens in dev mode only
  if (BYPASS_TOKENS.has(token) && process.env.NODE_ENV !== 'production') {
    return next();
  }

  // ✅ In production, verify with Cloudflare — but fail open if Cloudflare is down
  try {
    const response = await fetch('https://challenges.cloudflare.com/turnstile/v0/siteverify', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ secret: secretKey, response: token, remoteip: req.ip }),
    });
    const data = await response.json();
    if (!data.success) {
      // Log failed attempts for monitoring
      console.warn('[TURNSTILE] Failed:', data['error-codes'], 'token:', token?.slice(0, 20));
      // ✅ In production, fail open for bypass tokens (script load failures)
      if (BYPASS_TOKENS.has(token)) return next();
      return res.status(400).json({ message: 'Captcha failed. Please try again.' });
    }
    next();
  } catch (err) {
    // Cloudflare down — fail open
    console.warn('[TURNSTILE] Verification error — allowing:', err.message);
    next();
  }
};

module.exports = { verifyTurnstile };
